-- Align every SQ1 Cube Shape case with Squanmate's canonical 170-case table.
-- The payload includes the exact pre-migration names, groups, setups, and formulas.
-- Any drift aborts the migration before data or user-owned keys are changed.

CREATE TEMP TABLE _sq1_cs_alignment (
  id BIGINT PRIMARY KEY,
  position INTEGER NOT NULL UNIQUE,
  expected_name TEXT NOT NULL,
  expected_subgroup TEXT NOT NULL,
  expected_setup TEXT NOT NULL,
  expected_algs JSONB NOT NULL,
  canonical_name TEXT NOT NULL UNIQUE,
  canonical_subgroup TEXT NOT NULL,
  canonical_setup TEXT NOT NULL,
  canonical_algs JSONB NOT NULL
) ON COMMIT DROP;

