$sq1_cs$::jsonb) AS row_data(
  i BIGINT,
  p INTEGER,
  en TEXT,
  eg TEXT,
  ep TEXT,
  ea JSONB,
  n TEXT,
  g TEXT,
  s TEXT,
  a JSONB
);

DO $$
DECLARE
  payload_count INTEGER;
  current_count INTEGER;
  mismatch_count INTEGER;
BEGIN
  SELECT count(*) INTO payload_count FROM _sq1_cs_alignment;
  IF payload_count <> 170 THEN
    RAISE EXCEPTION 'SQ1 CS alignment payload must contain 170 rows, got %', payload_count;
  END IF;

  SELECT count(*) INTO current_count
  FROM alg_cases
  WHERE puzzle = 'sq1' AND set_slug = 'cs';
  IF current_count <> 170 THEN
    RAISE EXCEPTION 'Expected 170 current SQ1 CS rows, got %', current_count;
  END IF;

  SELECT count(*) INTO mismatch_count
  FROM _sq1_cs_alignment a
  LEFT JOIN alg_cases c
    ON c.id = a.id
   AND c.puzzle = 'sq1'
   AND c.set_slug = 'cs'
  WHERE c.id IS NULL
     OR c.position <> a.position
     OR c.name <> a.expected_name
     OR c.subgroup <> a.expected_subgroup
     OR c.setup <> a.expected_setup
     OR c.algs <> a.expected_algs;
  IF mismatch_count <> 0 THEN
    RAISE EXCEPTION 'SQ1 CS source snapshot drifted in % rows; refusing partial alignment', mismatch_count;
  END IF;
END $$;

CREATE TEMP TABLE _sq1_cs_key_map ON COMMIT DROP AS
SELECT
  expected_subgroup || '|' || expected_name AS old_key,
  canonical_subgroup || '|' || canonical_name AS new_key
FROM _sq1_cs_alignment
WHERE expected_subgroup <> canonical_subgroup
   OR expected_name <> canonical_name;

UPDATE alg_cases c
SET
  name = a.canonical_name,
  subgroup = a.canonical_subgroup,
  setup = a.canonical_setup,
  sticker = '{"kind":"raw","tag":"sqcube","attrs":{}}'::jsonb,
  algs = a.canonical_algs
FROM _sq1_cs_alignment a
WHERE c.id = a.id
  AND c.puzzle = 'sq1'
  AND c.set_slug = 'cs';

UPDATE alg_submissions submission
SET case_name = a.canonical_name
FROM _sq1_cs_alignment a
WHERE submission.puzzle = 'sq1'
  AND submission.set_slug = 'cs'
  AND submission.case_name = a.expected_name
  AND a.expected_name <> a.canonical_name;

CREATE TEMP TABLE _sq1_cs_marks ON COMMIT DROP AS
SELECT DISTINCT ON (mark.wca_id, COALESCE(map.new_key, mark.case_key))
  mark.wca_id,
  mark.puzzle,
  mark.set_slug,
  COALESCE(map.new_key, mark.case_key) AS case_key,
  mark.status,
  mark.updated_at
FROM alg_case_marks mark
LEFT JOIN _sq1_cs_key_map map ON map.old_key = mark.case_key
WHERE mark.puzzle = 'sq1' AND mark.set_slug = 'cs'
ORDER BY
  mark.wca_id,
  COALESCE(map.new_key, mark.case_key),
  mark.updated_at DESC,
  (map.new_key IS NULL) DESC;

DELETE FROM alg_case_marks WHERE puzzle = 'sq1' AND set_slug = 'cs';
INSERT INTO alg_case_marks (wca_id, puzzle, set_slug, case_key, status, updated_at)
SELECT wca_id, puzzle, set_slug, case_key, status, updated_at
FROM _sq1_cs_marks;

CREATE TEMP TABLE _sq1_cs_srs ON COMMIT DROP AS
SELECT DISTINCT ON (srs.wca_id, COALESCE(map.new_key, srs.case_key))
  srs.wca_id,
  srs.puzzle,
  srs.set_slug,
  COALESCE(map.new_key, srs.case_key) AS case_key,
  srs.due,
  srs.ivl,
  srs.ease,
  srs.reps,
  srs.lapses,
  srs.streak,
  srs.hist,
  srs.reviewed_at
FROM alg_case_srs srs
LEFT JOIN _sq1_cs_key_map map ON map.old_key = srs.case_key
WHERE srs.puzzle = 'sq1' AND srs.set_slug = 'cs'
ORDER BY
  srs.wca_id,
  COALESCE(map.new_key, srs.case_key),
  srs.reviewed_at DESC,
  (map.new_key IS NULL) DESC;

DELETE FROM alg_case_srs WHERE puzzle = 'sq1' AND set_slug = 'cs';
INSERT INTO alg_case_srs (
  wca_id, puzzle, set_slug, case_key, due, ivl, ease,
  reps, lapses, streak, hist, reviewed_at
)
SELECT
  wca_id, puzzle, set_slug, case_key, due, ivl, ease,
  reps, lapses, streak, hist, reviewed_at
FROM _sq1_cs_srs;

CREATE TEMP TABLE _sq1_cs_rooms ON COMMIT DROP AS
SELECT
  room.code,
  (
    SELECT COALESCE(jsonb_agg(mapped.case_key ORDER BY mapped.first_ordinality), '[]'::jsonb)
    FROM (
      SELECT COALESCE(map.new_key, item.value) AS case_key, min(item.ordinality) AS first_ordinality
      FROM jsonb_array_elements_text(room.keys) WITH ORDINALITY AS item(value, ordinality)
      LEFT JOIN _sq1_cs_key_map map ON map.old_key = item.value
      GROUP BY COALESCE(map.new_key, item.value)
    ) mapped
  ) AS keys,
  (
    SELECT COALESCE(jsonb_agg(mapped.case_key ORDER BY mapped.first_ordinality), '[]'::jsonb)
    FROM (
      SELECT COALESCE(map.new_key, item.value) AS case_key, min(item.ordinality) AS first_ordinality
      FROM jsonb_array_elements_text(room.queue) WITH ORDINALITY AS item(value, ordinality)
      LEFT JOIN _sq1_cs_key_map map ON map.old_key = item.value
      GROUP BY COALESCE(map.new_key, item.value)
    ) mapped
  ) AS queue
FROM trainer_rooms room
WHERE room.puzzle = 'sq1' AND room.set_slug = 'cs';

UPDATE trainer_rooms room
SET
  keys = migrated.keys,
  queue = migrated.queue,
  total = jsonb_array_length(migrated.queue),
  next_index = least(room.next_index, jsonb_array_length(migrated.queue))
FROM _sq1_cs_rooms migrated
WHERE room.code = migrated.code;

UPDATE alg_chain_orders chain
SET case_keys = (
  SELECT COALESCE(jsonb_agg(mapped.case_key ORDER BY mapped.first_ordinality), '[]'::jsonb)
  FROM (
    SELECT
      COALESCE(map.new_key, item.value) AS case_key,
      min(item.ordinality) AS first_ordinality
    FROM jsonb_array_elements_text(chain.case_keys) WITH ORDINALITY AS item(value, ordinality)
    LEFT JOIN _sq1_cs_key_map map ON map.old_key = item.value
    GROUP BY COALESCE(map.new_key, item.value)
  ) mapped
)
WHERE chain.puzzle = 'sq1' AND chain.set_slug = 'cs';

UPDATE alg_preferred_algs preferred
SET items = (
  SELECT COALESCE(jsonb_object_agg(chosen.slot, chosen.ref), '{}'::jsonb)
  FROM (
    SELECT DISTINCT ON (candidate.slot)
      candidate.slot,
      candidate.ref
    FROM (
      SELECT
        COALESCE(map.new_key, split_part(item.key, '::', 1))
          || substring(item.key FROM length(split_part(item.key, '::', 1)) + 1) AS slot,
        item.value AS ref,
        (map.new_key IS NULL) AS already_canonical
      FROM jsonb_each_text(preferred.items) AS item
      LEFT JOIN _sq1_cs_key_map map
        ON map.old_key = split_part(item.key, '::', 1)
    ) candidate
    ORDER BY candidate.slot, candidate.already_canonical DESC
  ) chosen
)
WHERE preferred.puzzle = 'sq1' AND preferred.set_slug = 'cs';

DO $$
DECLARE
  mismatch_count INTEGER;
  distinct_name_count INTEGER;
BEGIN
  SELECT count(*) INTO mismatch_count
  FROM _sq1_cs_alignment a
  LEFT JOIN alg_cases c
    ON c.id = a.id
   AND c.puzzle = 'sq1'
   AND c.set_slug = 'cs'
  WHERE c.id IS NULL
     OR c.position <> a.position
     OR c.name <> a.canonical_name
     OR c.subgroup <> a.canonical_subgroup
     OR c.setup <> a.canonical_setup
     OR c.sticker <> '{"kind":"raw","tag":"sqcube","attrs":{}}'::jsonb
     OR c.algs <> a.canonical_algs;
  IF mismatch_count <> 0 THEN
    RAISE EXCEPTION 'SQ1 CS alignment post-check failed in % rows', mismatch_count;
  END IF;

  SELECT count(DISTINCT name) INTO distinct_name_count
  FROM alg_cases
  WHERE puzzle = 'sq1' AND set_slug = 'cs';
  IF distinct_name_count <> 170 THEN
    RAISE EXCEPTION 'Expected 170 unique canonical SQ1 CS names, got %', distinct_name_count;
  END IF;

  SELECT count(*) INTO mismatch_count
  FROM (
    SELECT case_key FROM alg_case_marks WHERE puzzle = 'sq1' AND set_slug = 'cs'
    UNION ALL
    SELECT case_key FROM alg_case_srs WHERE puzzle = 'sq1' AND set_slug = 'cs'
    UNION ALL
    SELECT item.value
    FROM trainer_rooms room
    CROSS JOIN LATERAL jsonb_array_elements_text(room.keys || room.queue) AS item(value)
    WHERE room.puzzle = 'sq1' AND room.set_slug = 'cs'
    UNION ALL
    SELECT item.value
    FROM alg_chain_orders chain
    CROSS JOIN LATERAL jsonb_array_elements_text(chain.case_keys) AS item(value)
    WHERE chain.puzzle = 'sq1' AND chain.set_slug = 'cs'
    UNION ALL
    SELECT split_part(item.key, '::', 1)
    FROM alg_preferred_algs preferred
    CROSS JOIN LATERAL jsonb_each(preferred.items) AS item(key, value)
    WHERE preferred.puzzle = 'sq1' AND preferred.set_slug = 'cs'
  ) stored
  JOIN _sq1_cs_key_map map ON map.old_key = stored.case_key;
  IF mismatch_count <> 0 THEN
    RAISE EXCEPTION 'Found % stale SQ1 CS user keys after migration', mismatch_count;
  END IF;
END $$;
